export const staffInfo=id=>EXTRA_STAFF.find(n=>n.id===id);
export const onDuty=(s,n)=>!!n&&s.minute>=n.start&&s.minute<n.end;
export const staffScene=(id,topic,index=0)=>{const n=staffInfo(id);return n?.scenes.find(x=>x[0]===topic)||n?.scenes[index%n.scenes.length];};
export function staffScript(s,p,topic,index){const scene=staffScene(p.id,topic,index);if(!scene)return null;const [key,title,opening,detail,plan,follow]=scene,relation=s.npcRelations[p.id]??50;
 const prefix=index===0?'':index%3===1?'지난번에 나눈 내용을 떠올리며 다시 살펴볼게요. ':index%3===2?'이번에는 바뀐 점부터 먼저 듣고 싶습니다. ':'확인할 자료를 꺼내 두었습니다. ';
 return {opening:prefix+opening+(relation>=65?' 편하게 다른 의견도 말씀해 주세요.':''),choices:[['현재 확인한 상황부터 나누겠습니다.','학생에게 필요한 방법을 함께 검토해요.','서로 맡을 일과 확인 시간을 나눌까요?'],['구체적인 자료와 담당 범위를 정하겠습니다.','현재 방법을 적용한 뒤 실제 모습을 살피겠습니다.','다음 협의에 필요한 확인 사항을 남기겠습니다.']],answers:[[detail,plan,title+'에 관해서는 '+detail],[plan,follow,follow+' 합의되지 않은 내용은 확정으로 남기지 않겠습니다.']]};
}
